<?php
namespace App\Http\Controllers;use App\Models\{Committee,CommitteeReport};use App\Services\CommitteeReportService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;class CommitteeReportController extends Controller{public function store(Committee $committee,Request $request,CommitteeReportService $service){$data=$request->validate(['report_type'=>'required|in:quarterly,annual,internal','period_start'=>'required|date','period_end'=>'required|date|after_or_equal:period_start']);$service->generate($committee,$data['report_type'],$data['period_start'],$data['period_end'],$request->user()->id);return back()->with('success','Informe generado.');}public function download(CommitteeReport $report){abort_unless($report->document_path&&Storage::disk('public')->exists($report->document_path),404);return Storage::disk('public')->download($report->document_path);}}
